      "title": "S3 public access block is not configured",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks account-independent controls preventing public ACLs and bucket policies, increasing the risk of accidental public exposure."
    },
