      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Flow log objects cannot be recovered from accidental overwrite or deletion because bucket versioning is not enabled."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not use KMS encryption by default",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The bucket has no explicit default SSE-KMS configuration, so it lacks KMS-backed encryption controls and auditability for stored flow logs."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket permits destructive deletion",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The force_destroy setting allows Terraform to delete the bucket together with all flow log versions, increasing the impact of accidental or malicious infrastructure deletion."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket does not enforce encrypted transport",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "No bucket policy denies requests made without TLS, allowing authorized clients to transmit flow logs or related data over insecure HTTP connections."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

